import random
import string
from typing import List, Tuple

# Target datatype: lookup key string for NameValue list produced by ParseNameValue
# The fuzzer stub calls GetValueFromNameValueList(pdata, name) where name is a C string
# Our goal: generate interesting, valid key names that are likely to be present in
# UPnP SOAP/XML responses parsed by miniupnpc. We avoid malformed inputs and stay under 4096 bytes.

# Common UPnP/WANIP/WANCommon/Firewall keys frequently seen in MiniUPnPc NameValue parsing
COMMON_KEYS = [
    # Generic SOAP/UPnP
    "NewStatus", "NewUptime", "NewLastConnectionError",
    "NewExternalIPAddress", "NewConnectionType",
    # Port mapping specific
    "NewRemoteHost", "NewExternalPort", "NewProtocol", "NewInternalPort",
    "NewInternalClient", "NewEnabled", "NewDescription", "NewLeaseTime",
    # Generic entry fields (enumeration APIs)
    "NewPortMappingIndex", "NewPortMappingDescription",
    # WANCommonInterfaceConfig counters
    "NewTotalBytesSent", "NewTotalBytesReceived",
    "NewTotalPacketsSent", "NewTotalPacketsReceived",
    # Link properties
    "NewLayer1UpstreamMaxBitRate", "NewLayer1DownstreamMaxBitRate",
    # IGD device/service URLs
    "controlURL", "eventSubURL", "SCPDURL", "serviceType",
    # IPv6 Firewall Control
    "NewFirewallEnabled", "NewInboundPinholeAllowed",
    "NewUniqueID", "NewOutboundPinholeTimeout",
    # Error/info strings
    "errorCode", "errorDescription",
]

# Variations for case and namespace prefixes sometimes used
PREFIXES = [
    "", "urn:schemas-upnp-org:service:", "u:", "s:",
]

# Additional plausible service/type tokens to prepend/append
SERVICE_TOKENS = [
    "WANIPConnection:", "WANIPConnection:1:", "WANIPConnection:2:",
    "WANPPPConnection:", "WANCommonInterfaceConfig:", "WANIPv6FirewallControl:",
]

# Some exact strings that commonly appear as keys without New- prefix
EXTRA_KEYS = [
    "connectionStatus", "LastConnectionError", "ExternalIPAddress",
    "ConnectionType", "PortMappingNumberOfEntries",
]

# Generate mixed-case variants to cover case-sensitive/insensitive parsers
def case_variants(s: str, rnd: random.Random) -> str:
    if not s:
        return s
    mode = rnd.choice(["lower", "upper", "title", "mixed", "as_is"]) 
    if mode == "lower":
        return s.lower()
    if mode == "upper":
        return s.upper()
    if mode == "title":
        return s.title()
    if mode == "mixed":
        chars = []
        for c in s:
            if c.isalpha():
                chars.append(rnd.choice([c.lower(), c.upper()]))
            else:
                chars.append(c)
        return "".join(chars)
    return s

def random_token(rnd: random.Random, length: int) -> str:
    alnum = string.ascii_letters + string.digits
    return "".join(rnd.choice(alnum) for _ in range(length))

def build_key(rnd: random.Random) -> str:
    # Choose strategy to produce a likely-present key
    strategy = rnd.choices(
        population=["common", "extra", "prefixed", "service_scoped", "synthetic"],
        weights=[40, 10, 20, 20, 10],
        k=1
    )[0]

    if strategy == "common":
        base = rnd.choice(COMMON_KEYS)
        return case_variants(base, rnd)

    if strategy == "extra":
        base = rnd.choice(EXTRA_KEYS)
        return case_variants(base, rnd)

    if strategy == "prefixed":
        prefix = rnd.choice(PREFIXES)
        base = rnd.choice(COMMON_KEYS + EXTRA_KEYS)
        return prefix + case_variants(base, rnd)

    if strategy == "service_scoped":
        token = rnd.choice(SERVICE_TOKENS)
        base = rnd.choice(COMMON_KEYS + EXTRA_KEYS)
        # Sometimes concatenate with a separator frequently seen in parsed names
        sep = rnd.choice(["", ":", "/", "."])  # Keep it simple and valid
        return token + sep + case_variants(base, rnd)

    # synthetic fallback: looks like NewXxx style with reasonable field name
    head = rnd.choice(["New", "", "X-"])
    field_core = rnd.choice([
        "Status", "Uptime", "ExternalPort", "InternalPort", "InternalClient",
        "Protocol", "Enabled", "Description", "LeaseTime", "RemoteHost",
        "Index", "Duration", "UniqueID", "FirewallEnabled"
    ])
    tail = rnd.choice(["", "Value", "Info", "Name"])
    key = head + field_core + tail
    # Light randomization
    if rnd.random() < 0.3:
        key += rnd.choice(["", "_", "-"]) + random_token(rnd, rnd.randint(1, 3))
    return case_variants(key, rnd)


def encode_c_string(s: str) -> bytes:
    # Ensure ASCII-safe; substitute any non-ASCII with underscore
    b = bytearray()
    for ch in s:
        code = ord(ch)
        if 32 <= code <= 126:
            b.append(code)
        else:
            b.append(ord('_'))
    # NUL-terminate to satisfy typical C string expectations
    b.append(0)
    return bytes(b)


def generate(seed: int) -> bytes:
    rnd = random.Random(seed)

    # Build a small corpus of multiple candidate keys concatenated with NULs.
    # FUZZ_PARAM_STR likely consumes up to the first NUL-terminated string, but
    # some harnesses may utilize more; keeping multiple keys increases chance of hits
    # while still being valid strings when read from the start.
    count = rnd.randint(1, 6)
    keys: List[str] = [build_key(rnd) for _ in range(count)]

    # Bias: include a couple of very common exact names at the beginning sometimes
    if rnd.random() < 0.6:
        bias = ["NewExternalIPAddress", "NewStatus", "NewUptime"]
        keys = bias[: rnd.randint(1, len(bias))] + keys

    # Ensure total size <= 4096
    out = bytearray()
    for k in keys:
        kb = encode_c_string(k)
        if len(out) + len(kb) > 4096:
            break
        out.extend(kb)

    # Guarantee at least one NUL-terminated string
    if not out:
        out = bytearray(encode_c_string("NewStatus"))

    return bytes(out)
